                output["predictions"][j] = {
                    "label": inputs["text"][i]["choices"][pred["label"]],
                    "score": pred["score"],
                }

        return outputs

    def predict(self, texts):
        inputs = self.preprocess(texts)
        outputs = self.infer(inputs)
        results = self.postprocess(outputs)
        return results


