        "原告赵六，2022年5月29日生\n委托代理人孙七，深圳市C律师事务所律师。\n被告周八，1990年7月28日出生\n委托代理人吴九，山东D律师事务所律师",
    ]
    schema1 = ["法院", {"原告": "委托代理人"}, {"被告": "委托代理人"}]
    args.schema = schema1
    uie = UIEPredictor(args)
    print("-----------------------------")
    outputs = uie.predict(texts)
    for text, output in zip(texts, outputs):
